#!/usr/bin/env Rscript
Sys.setenv(TORCH_VERIFY_LOAD="FALSE")
suppressPackageStartupMessages({library(torch); library(LBBNN); library(jsonlite)})
args <- commandArgs(trailingOnly=TRUE)
getarg <- function(k, default=NULL){ i<-match(paste0("--",k),args); if(is.na(i)) return(default); args[[i+1L]] }
data_dir<-getarg("data-dir"); out_file<-getarg("out","r_methods.csv"); seed<-as.integer(getarg("seed","100400")); epochs<-as.integer(getarg("epochs","2000")); draws<-as.integer(getarg("draws","500")); device<-tolower(getarg("device","auto")); if(device=="auto") device<-if(torch::cuda_is_available()) "cuda" else "cpu"; h1<-20L; h2<-20L; batch<-128L
rv<-function(p) as.numeric(read.csv(p,header=FALSE)[[1]]); rm<-function(p) as.matrix(read.csv(p,header=FALSE)); d<-normalizePath(data_dir,mustWork=TRUE); Xtr<-rm(file.path(d,"X_train.csv")); ytr<-rv(file.path(d,"y_train.csv")); Xte<-rm(file.path(d,"X_test.csv")); yte<-rv(file.path(d,"y_test.csv")); signal<-rv(file.path(d,"signal_test.csv")); truth<-rv(file.path(d,"feature_true.csv"))>.5; meta<-jsonlite::read_json(file.path(d,"meta.json"),simplifyVector=TRUE); p<-ncol(Xtr)
train_dl<-dataloader(tensor_dataset(torch_tensor(Xtr,dtype=torch_float()),torch_tensor(ytr,dtype=torch_float())),batch_size=min(batch,nrow(Xtr)),shuffle=TRUE); test_dl<-dataloader(tensor_dataset(torch_tensor(Xte,dtype=torch_float()),torch_tensor(yte,dtype=torch_float())),batch_size=nrow(Xte),shuffle=FALSE)
mean_pred<-function(x){a<-as.array(x$detach()$cpu()); if(length(dim(a))==3L) return(as.numeric(apply(a,c(2,3),mean)[,1])); if(length(dim(a))==2L) return(as.numeric(colMeans(a))); as.numeric(a)}
orient<-function(x,nout,nin){a<-as.array(x$detach()$cpu())>0; if(all(dim(a)==c(nout,nin))) return(a); if(all(dim(a)==c(nin,nout))) return(t(a)); stop("unexpected mask shape")}
path_stats<-function(model,input_skip){W1<-orient(model$layers$children[[1]]$alpha_active_path,h1,p); if(input_skip){W2<-orient(model$layers$children[[2]]$alpha_active_path,h2,h1+p); W3<-orient(model$out_layer$alpha_active_path,1,h2+p); W2h<-W2[,1:h1,drop=FALSE]; W2x<-W2[,h1+(1:p),drop=FALSE]; W3h<-W3[,1:h2,drop=FALSE]; W3x<-W3[,h2+(1:p),drop=FALSE]; active_paths<-sum((W3h*1)%*%(W2h*1)%*%(W1*1))+sum((W3h*1)%*%(W2x*1))+sum(W3x); total_paths<-p*h1*h2+p*h2+p; selected<-colSums(W1)>0 | colSums(W2x)>0 | as.logical(W3x[1,]); candidate<-length(W1)+length(W2)+length(W3); retained<-sum(W1)+sum(W2)+sum(W3)} else {W2<-orient(model$layers$children[[2]]$alpha_active_path,h2,h1); W3<-orient(model$out_layer$alpha_active_path,1,h2); active_paths<-sum((W3*1)%*%(W2*1)%*%(W1*1)); total_paths<-p*h1*h2; selected<-colSums(W1)>0; candidate<-length(W1)+length(W2)+length(W3); retained<-sum(W1)+sum(W2)+sum(W3)}; list(selected=selected,dparam=retained/candidate,path_density=active_paths/total_paths)}
metrics<-function(pred){mse<-mean((pred-signal)^2); r2<-1-sum((pred-signal)^2)/sum((signal-mean(signal))^2); c(mse=mse,r2=r2)}
feature_scores_lbbnn<-function(model,input_skip){
  if(!input_skip){
    a<-model$layers$children[[1]]$alpha$clone()$detach()$cpu()
    return(as.numeric(a$mean(dim=1)))
  }
  mats<-list()
  for(l in model$layers$children){
    a<-as.array(l$alpha$clone()$detach()$cpu())
    mats[[length(mats)+1L]]<-a[, (ncol(a)-p+1L):ncol(a), drop=FALSE]
  }
  a<-as.array(model$out_layer$alpha$clone()$detach()$cpu())
  mats[[length(mats)+1L]]<-a[, (ncol(a)-p+1L):ncol(a), drop=FALSE]
  colMeans(do.call(rbind,mats))
}
topk_string<-function(score,k=10L){paste(order(score,decreasing=TRUE)[seq_len(min(k,length(score)))]-1L,collapse=";")}
run_lbbnn<-function(label,flow,input_skip){torch_manual_seed(seed); sizes<-c(p,h1,h2,1L); model<-lbbnn_net(problem_type="regression",sizes=sizes,prior=rep(.5,3),std=rep(1,3),inclusion_inits="polarized",input_skip=input_skip,flow=flow,num_transforms=2,dims=c(50,50),device=device,bias_inclusion_prob=FALSE,weight_init="he"); t0<-proc.time()[[3]]; suppressMessages(train_lbbnn(epochs=epochs,LBBNN=model,lr=.01,train_dl=train_dl,device=device,verbose=FALSE)); runtime<-proc.time()[[3]]-t0; if(input_skip) model$compute_paths_input_skip() else model$compute_paths(); ps<-path_stats(model,input_skip); pred<-mean_pred(predict(model,newdata=test_dl,mpm=TRUE,draws=draws,device=device)); fm<-metrics(pred); fs<-feature_scores_lbbnn(model,input_skip); data.frame(method=label,condition=meta$condition,data_seed=meta$seed,fit_seed=seed,mse=fm['mse'],r2=fm['r2'],dparam=ps$dparam,network_density=as.numeric(model$density()),path_density=ps$path_density,runtime_sec=runtime,topk_indices=topk_string(fs,10L))}
ISANN<-nn_module("ISANN",initialize=function(p,h1,h2){self$p<-p;self$h1<-h1;self$h2<-h2;self$f1<-nn_linear(p,h1);self$f2<-nn_linear(h1+p,h2);self$out<-nn_linear(h2+p,1)},forward=function(x){h<-nnf_relu(self$f1(x));h2<-nnf_relu(self$f2(torch_cat(list(h,x),dim=2)));self$out(torch_cat(list(h2,x),dim=2))$squeeze(2)})
run_ann<-function(){torch_manual_seed(seed); m<-ISANN(p,h1,h2)$to(device=device); op<-optim_adam(m$parameters,lr=.01); t0<-proc.time()[[3]]; for(ep in seq_len(epochs)){m$train(); coro::loop(for(b in train_dl){x<-b[[1]]$to(device=device);y<-b[[2]]$to(device=device);op$zero_grad();pred<-m(x)$view_as(y); l1<-m$f1$weight$abs()$sum()+m$f2$weight$abs()$sum()+m$out$weight$abs()$sum(); loss<-nnf_mse_loss(pred,y)+.01*l1;loss$backward();op$step()})}; runtime<-proc.time()[[3]]-t0; raw1<-abs(as.array(m$f1$weight$detach()$cpu())); raw2<-abs(as.array(m$f2$weight$detach()$cpu())); raw3<-abs(as.array(m$out$weight$detach()$cpu())); feature_score<-colSums(raw1)+colSums(raw2[,h1+(1:p),drop=FALSE])+as.numeric(raw3[1,h2+(1:p)]); topk<-topk_string(feature_score,10L); w1<-raw1>=.005; w2<-raw2>=.005; w3<-raw3>=.005; w2h<-w2[,1:h1,drop=FALSE];w2x<-w2[,h1+(1:p),drop=FALSE];w3h<-w3[,1:h2,drop=FALSE];w3x<-w3[,h2+(1:p),drop=FALSE]; h1reach<-rowSums(w1)>0; h2out<-as.logical(w3h[1,]); h1out<-if(any(h2out)) colSums(w2h[h2out,,drop=FALSE])>0 else rep(FALSE,h1); h2reach<-(if(any(h1reach)) rowSums(w2h[,h1reach,drop=FALSE])>0 else rep(FALSE,h2))|rowSums(w2x)>0; a1<-w1 & matrix(h1out,nrow=h1,ncol=p); a2h<-w2h & outer(h2out,h1reach,"&"); a2x<-w2x & matrix(h2out,nrow=h2,ncol=p); a3h<-w3h & matrix(h2reach,nrow=1,ncol=h2); a3x<-w3x; candidate<-length(w1)+length(w2)+length(w3); retained<-sum(a1)+sum(a2h)+sum(a2x)+sum(a3h)+sum(a3x); raw<-sum(w1)+sum(w2)+sum(w3); active_paths<-sum((a3h*1)%*%(a2h*1)%*%(a1*1))+sum((a3h*1)%*%(a2x*1))+sum(a3x); total_paths<-p*h1*h2+p*h2+p; with_no_grad({m$f1$weight$mul_(torch_tensor(a1*1,dtype=torch_float(),device=device));m$f2$weight$mul_(torch_tensor(cbind(a2h,a2x)*1,dtype=torch_float(),device=device));m$out$weight$mul_(torch_tensor(cbind(a3h,a3x)*1,dtype=torch_float(),device=device))}); m$eval(); pr<-c();with_no_grad({coro::loop(for(b in test_dl){pr<-c(pr,as.numeric(m(b[[1]]$to(device=device))$detach()$cpu()))})});fm<-metrics(pr);data.frame(method="IS-ANN-L1",condition=meta$condition,data_seed=meta$seed,fit_seed=seed,mse=fm['mse'],r2=fm['r2'],dparam=retained/candidate,network_density=raw/candidate,path_density=active_paths/total_paths,runtime_sec=runtime,topk_indices=topk)}
ans<-rbind(run_lbbnn("LBBNN-LRT",FALSE,FALSE),run_lbbnn("LBBNN-FLOW",TRUE,FALSE),run_lbbnn("ISLaB-FLOW",TRUE,TRUE),run_ann()); write.csv(ans,out_file,row.names=FALSE); print(ans)
